const e={title:"TripReel - Free Travel Animation App: Turn Photos Into Beautiful Videos",description:"Create stunning travel videos with animated maps and flight routes. Free travel animation app with 3D globe route mapping. Turn your photos into beautiful journey videos automatically. Privacy-first, works offline.",keywords:"travel animation app, travel map animation app, travel route animation app, flight animation app, travel video maker, automatic travel video, animated travel map, flight path animation, journey animation, globe animation, travel recap video, photo to video, trip highlights, free travel app, offline video maker, privacy travel app, camera roll video"},t={logoAlt:"TripReel Logo",appName:"TripReel",howItWorks:"How It Works",video:"Video",features:"Features",theApp:"The app"},o={badge:"Turn Photos Into Travel Stories",title1:"Your Camera Roll,",title2:"Fully Tapped",description:"TripReel automatically creates beautiful travel videos from your photos' locations. Watch your journeys come alive with stunning animated route maps and flight paths across a 3D globe, all while keeping your data private and secure.",secure:"100% Secure",worksOffline:"Works Offline",globeAlt:"TripReel Globe Animation"},a={title:"How It Works",subtitle:"Three simple steps to create your perfect travel video",step1:{title:"Allow Photo Access",description:"Grant TripReel access to your photo library. The app only reads location metadata, nothing else."},step2:{title:"Automatic Trip Detection",description:"TripReel analyzes location metadata and intelligently finds your trips based on dates and locations."},step3:{title:"Generate Your Video",description:"Watch as your journey unfolds on a beautiful globe animation, ready to share on social media."}},i={title:"See The Magic Happen",subtitle:"Watch how TripReel transforms your photo library into amazing travel videos",caption:"This is what your final travel video can look like"},r={title:"Everything You Need",subtitle:"Powerful features designed for modern travelers",twoTap:{title:"Two-Tap Travel Videos",description:"Create stunning travel recap videos from your photo library in just two taps. No editing required."},smartTrip:{title:"Smart Trip Detection",description:"Automatically finds and groups your trips by analyzing dates and location metadata from your photos."},globe:{title:"Beautiful Globe Animation",description:"Watch your journey come to life with a stunning 3D globe showing your animated travel routes and flight paths across the world."},privacy:{title:"Privacy First",description:"Everything processes on your device. Your photos never leave your phone. Works in airplane mode."},customStyles:{title:"Custom Styles",description:"Choose from multiple earth styles and customizations to match your aesthetic and make each video unique."},manualControl:{title:"Manual Control",description:"You can manually add entirely new trips if location services weren't enabled on your device."}},n={title:"Creative Video Ideas",subtitle:"Get inspired with what you can create using TripReel. From quick weekend getaways to year-long adventures, create stunning travel videos for every journey.",description:"Whether you're creating a travel map animation, documenting a flight route, or making a year-end travel recap, TripReel makes it effortless to transform your memories into shareable videos.",ideas:{yearRecap:{title:"2025 Travel Recap",description:"Create your 2025 yearly travel recap video automatically"},europeRoadTrip:{title:"Europe Road Trip",description:"Showcase your European adventure with animated route maps"},southeastAsia:{title:"Southeast Asia Journey",description:"Visualize your backpacking route across multiple countries"},japanRail:{title:"Japan Rail Journey",description:"Create map videos of your train routes across Japan"},crossCountry:{title:"Cross-Country USA",description:"Turn your American road trip into an epic route video"},islandHopping:{title:"Island Hopping",description:"Show your island-to-island travels with stunning 3D animations"},worldTour:{title:"World Tour Montage",description:"Multiple trips into one amazing global journey video"},travelPlans:{title:"2026 Travel Plans",description:"Visualize and plan your exciting travel adventures for 2026"},lifetimeTravel:{title:"Lifetime Travel Story",description:"Create a video showcasing all your life-long travels"},regionalExplorer:{title:"Regional Explorer",description:"Chart your adventures across states, provinces, and regions"},festivalCircuit:{title:"Festival Circuit",description:"Map out your music festival and event journey"},bikeRoutes:{title:"My City Breaks",description:"Showcase all your city escapades"}}},s={title:"The app",subtitle:"Available now on App Store",alt1:"Automatic Travel Videos - Create stunning videos in seconds",alt2:"Photo Location Detection - Uses your photos' metadata",alt3:"Trip Detection - Automatically groups your travels",alt4:"Beautiful Earth Videos - Globe animation of your journey",alt5:"Custom Styles - Personalize your travel videos"},l={comingSoon:"Coming Soon",androidTitle:"Android App Coming Soon!",androidMessage:'The Android version is not yet available but will be soon. Message me at <a href="mailto:marian@qod.ee?subject=TripReel%20Android%20App" class="text-sky-600 dark:text-sky-400 hover:text-sky-700 dark:hover:text-sky-300 font-semibold transition-colors">marian@qod.ee</a> and I\'ll let you know when it\'s ready!',gotIt:"Got it!"},u={title:"Frequently Asked Questions",subtitle:"Everything you need to know about TripReel",q1:{question:"Can I really use the app fully in airplane mode?",answer:"Yes! For premium users, the app can be used completely offline in airplane mode with no limitations. For non-premium users, some features are ad-supported which might require temporarily enabling internet, but for premium users there are no ads and the app can be fully used in airplane mode."},q2:{question:"I upgraded to Premium, how can I remove the watermark?",answer:"Many people ask what app was used to create these videos, so, after upgrading to premium, you have the option to add a smaller version of the watermark (with just the app name) or completely remove it if you wish."},q3:{question:"Is my photo data safe and private?",answer:"Absolutely! TripReel only reads location metadata from your photos - we never access, store, or transmit the actual photo content. All processing happens locally on your device, and no data ever leaves your phone. You can verify this by using the app in airplane mode - it works perfectly offline!"},q4:{question:"What if my photos don't have location data?",answer:"No problem! If location services weren't enabled when you took your photos, you can manually create trips and add locations yourself. The app gives you full control to customize your travel timeline."},q5:{question:"How does the app detect my trips automatically?",answer:"TripReel analyzes the location metadata and timestamps from your photos to intelligently identify when and where you traveled. It groups nearby locations and dates together to automatically detect your trips without any manual work required."},q6:{question:"Can I customize the appearance of my videos?",answer:"Yes! You can choose from multiple earth styles and customize various aspects of your animated travel videos to match your personal aesthetic. Premium users get access to additional route animation styles, map themes, and flight path options."},q7:{question:"Do I need to create an account?",answer:"No account required! TripReel works immediately after download. There's no registration, no login, and no personal information needed. Just download the app and start creating your travel videos right away."},q8:{question:"Why is a location missing from my trip?",answer:"The app can only work with available data, so first of all you need at least a couple of photos in that location. Secondly, you need to make sure you had location data enabled when you were there. Thirdly, sometimes low GPS reception can cause wrong location data. If you ruled out all these and your location still doesn't show up, you can manually add that location from the Trips Overview > Edit button. Please also use Contact to report the issue."},q9:{question:"Where can I share my awesome video?",answer:"Of course, you can also share it on all social platforms. To better suit the platform, the app allows different aspect ratios for your videos."},q10:{question:"Where can I report a bug?",answer:"Just contact me directly at marian@qod.ee, briefly explaining what the issue is."}},p={title:"Email Support",description:"If you have any feedback or encounter any issues, please feel free to contact me directly at this email and I'll personally read and handle your request as fast as possible. Thanks for using the app!",close:"Close"},d={default:{title:"🍪 Cookies",message:"We use cookies on the TripReel site to enhance your experience. No personal data collected.",accept:"Accept",decline:"Decline",details:"Details"},theme:{title:"🍪 Cookies",message:"🌙 To save your theme preference, you need to accept essential cookies on the TripReel site. Without them, your theme choice cannot be saved.",accept:"Accept",decline:"Decline",details:"Details"}},c={privacy:"App Privacy Policy",cookies:"Site Cookie Policy",contact:"Contact",cookiePreferences:"Cookie Preferences",madeWith:"Made with",forTravelers:"for travelers worldwide",copyright:"© {{year}} TripReel."},y={title:"Ready to Share Your Journey?",description:"Download TripReel today and transform your camera roll into beautiful travel videos with animated maps and routes. Your adventures deserve to be celebrated.",features:"Free to download • Fast & Convenient • Privacy guaranteed"},m={meta:e,header:t,hero:o,howItWorks:a,videoSection:i,features:r,videoIdeas:n,screenshots:s,appStore:l,faq:u,contact:p,cookieBanner:d,footer:c,cta:y};export{l as appStore,p as contact,d as cookieBanner,y as cta,m as default,u as faq,r as features,c as footer,t as header,o as hero,a as howItWorks,e as meta,s as screenshots,n as videoIdeas,i as videoSection};
